  "PROP-6a4369e9-inv-014": {
    "property_id": "PROP-6a4369e9-inv-014",
    "audit_result": {
      "property_id": "PROP-6a4369e9-inv-014",
      "classification": "potential-vulnerability",
      "code_path": "config/params/loader.go::UnmarshalConfig::L29-73",
      "proof_trace": "Config loader accepts fork epochs from YAML without validating strict ordering (Genesis < Altair < ... < Fulu). The merge() function silently sorts entries by epoch, allowing semantically invalid configs where fork version enums become decoupled from their intended epochs, potentially causing consensus failures in testnets/devnets.",
      "attack_scenario": "Misconfigured testnet YAML defines BELLATRIX_FORK_EPOCH < ALTAIR_FORK_EPOCH. Config loads successfully, schedule is epoch-sorted, but version-to-epoch mappings become incorrect, causing nodes to apply wrong fork rules at specific epochs and diverge from correctly-configured peers.",
      "checklist_id": "PROP-6a4369e9-inv-014"
    },
    "text": "Fork epoch constants must be strictly ordered: GENESIS < ALTAIR < ... < ELECTRA < FULU.",
    "assertion": "GENESIS_FORK_EPOCH < ALTAIR_FORK_EPOCH < BELLATRIX_FORK_EPOCH < ... < FULU_FORK_EPOCH",
    "covers": "SG-001",
    "severity": "HIGH",
    "type": "invariant"
  }
}

